DECLARE updates jsonb := $bank${"topic-practice":{"title":"Practice This Topic","revision":"lesson-1-exercises-v2","roundSize":10,"questions":[{"id":"lesson-1-v2-verb-forms-1","type":"multiple_choice","topic":"verb-forms","prompt":"What does ἄγει mean?","choices":[{"text":"he/she/it leads","correct":true},{"text":"he/she/it calls","correct":false},{"text":"he/she/it barks","correct":false},{"text":"he/she/it lives","correct":false}],"explanation":"Correct: he/she/it leads.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-2","type":"multiple_choice","topic":"verb-forms","prompt":"Which form means “he/she/it leads”?","choices":[{"text":"βαδίζει","correct":false},{"text":"βλέπει","correct":false},{"text":"θεραπεύει","correct":false},{"text":"ἄγει","correct":true}],"explanation":"Correct: ἄγει.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-3","type":"multiple_choice","topic":"verb-forms","prompt":"What person and number does ἄγει express?","choices":[{"text":"second person singular","correct":false},{"text":"third person plural","correct":false},{"text":"third person singular","correct":true},{"text":"first person singular","correct":false}],"explanation":"Correct: third person singular.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-4","type":"multiple_choice","topic":"verb-forms","prompt":"In ἄγει, how many people or things perform the action?","choices":[{"text":"one","correct":true},{"text":"two","correct":false},{"text":"more than one","correct":false}],"explanation":"ἄγει is third person singular.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-5","type":"multiple_choice","topic":"verb-forms","prompt":"Which stem remains when -ει is removed from ἄγει?","choices":[{"text":"ἀγ-","correct":true},{"text":"καλε-","correct":false},{"text":"ὑλακτε-","correct":false},{"text":"οἰκε-","correct":false}],"explanation":"The stem is ἀγ-; -ει is the present active third-person singular ending.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-6","type":"multiple_choice","topic":"verb-forms","prompt":"What does βαδίζει mean?","choices":[{"text":"he/she/it calls","correct":false},{"text":"he/she/it barks","correct":false},{"text":"he/she/it lives","correct":false},{"text":"he/she/it walks","correct":true}],"explanation":"Correct: he/she/it walks.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-7","type":"multiple_choice","topic":"verb-forms","prompt":"Which form means “he/she/it walks”?","choices":[{"text":"βλέπει","correct":false},{"text":"θεραπεύει","correct":false},{"text":"βαδίζει","correct":true},{"text":"ἄγει","correct":false}],"explanation":"Correct: βαδίζει.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-8","type":"multiple_choice","topic":"verb-forms","prompt":"What person and number does βαδίζει express?","choices":[{"text":"third person plural","correct":false},{"text":"third person singular","correct":true},{"text":"first person singular","correct":false},{"text":"second person singular","correct":false}],"explanation":"Correct: third person singular.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-9","type":"multiple_choice","topic":"verb-forms","prompt":"In βαδίζει, how many people or things perform the action?","choices":[{"text":"more than one","correct":false},{"text":"one","correct":true},{"text":"two","correct":false}],"explanation":"βαδίζει is third person singular.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-10","type":"multiple_choice","topic":"verb-forms","prompt":"Which stem remains when -ει is removed from βαδίζει?","choices":[{"text":"καλε-","correct":false},{"text":"ὑλακτε-","correct":false},{"text":"οἰκε-","correct":false},{"text":"βαδιζ-","correct":true}],"explanation":"The stem is βαδιζ-; -ει is the present active third-person singular ending.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-11","type":"multiple_choice","topic":"verb-forms","prompt":"What does βλέπει mean?","choices":[{"text":"he/she/it barks","correct":false},{"text":"he/she/it lives","correct":false},{"text":"he/she/it sees or looks","correct":true},{"text":"he/she/it calls","correct":false}],"explanation":"Correct: he/she/it sees or looks.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-12","type":"multiple_choice","topic":"verb-forms","prompt":"Which form means “he/she/it sees or looks”?","choices":[{"text":"θεραπεύει","correct":false},{"text":"βλέπει","correct":true},{"text":"ἄγει","correct":false},{"text":"βαδίζει","correct":false}],"explanation":"Correct: βλέπει.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-13","type":"multiple_choice","topic":"verb-forms","prompt":"What person and number does βλέπει express?","choices":[{"text":"third person singular","correct":true},{"text":"first person singular","correct":false},{"text":"second person singular","correct":false},{"text":"third person plural","correct":false}],"explanation":"Correct: third person singular.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-14","type":"multiple_choice","topic":"verb-forms","prompt":"In βλέπει, how many people or things perform the action?","choices":[{"text":"two","correct":false},{"text":"more than one","correct":false},{"text":"one","correct":true}],"explanation":"βλέπει is third person singular.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-15","type":"multiple_choice","topic":"verb-forms","prompt":"Which stem remains when -ει is removed from βλέπει?","choices":[{"text":"ὑλακτε-","correct":false},{"text":"οἰκε-","correct":false},{"text":"βλεπ-","correct":true},{"text":"καλε-","correct":false}],"explanation":"The stem is βλεπ-; -ει is the present active third-person singular ending.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-16","type":"multiple_choice","topic":"verb-forms","prompt":"What does θεραπεύει mean?","choices":[{"text":"he/she/it lives","correct":false},{"text":"he/she/it tends or takes care of","correct":true},{"text":"he/she/it calls","correct":false},{"text":"he/she/it barks","correct":false}],"explanation":"Correct: he/she/it tends or takes care of.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-17","type":"multiple_choice","topic":"verb-forms","prompt":"Which form means “he/she/it tends or takes care of”?","choices":[{"text":"θεραπεύει","correct":true},{"text":"ἄγει","correct":false},{"text":"βαδίζει","correct":false},{"text":"βλέπει","correct":false}],"explanation":"Correct: θεραπεύει.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-18","type":"multiple_choice","topic":"verb-forms","prompt":"What person and number does θεραπεύει express?","choices":[{"text":"first person singular","correct":false},{"text":"second person singular","correct":false},{"text":"third person plural","correct":false},{"text":"third person singular","correct":true}],"explanation":"Correct: third person singular.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-19","type":"multiple_choice","topic":"verb-forms","prompt":"In θεραπεύει, how many people or things perform the action?","choices":[{"text":"one","correct":true},{"text":"two","correct":false},{"text":"more than one","correct":false}],"explanation":"θεραπεύει is third person singular.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-20","type":"multiple_choice","topic":"verb-forms","prompt":"Which stem remains when -ει is removed from θεραπεύει?","choices":[{"text":"οἰκε-","correct":false},{"text":"θεραπευ-","correct":true},{"text":"καλε-","correct":false},{"text":"ὑλακτε-","correct":false}],"explanation":"The stem is θεραπευ-; -ει is the present active third-person singular ending.","sourceStatus":"Course-authored exercise"},{"id":"