at does λέγει mean?","choices":[{"text":"he/she/it calls","correct":false},{"text":"he/she/it barks","correct":false},{"text":"he/she/it lives","correct":false},{"text":"he/she/it says","correct":true}],"explanation":"Correct: he/she/it says.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-27","type":"multiple_choice","topic":"verb-forms","prompt":"Which form means “he/she/it says”?","choices":[{"text":"βαδίζει","correct":false},{"text":"βλέπει","correct":false},{"text":"λέγει","correct":true},{"text":"ἄγει","correct":false}],"explanation":"Correct: λέγει.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-28","type":"multiple_choice","topic":"verb-forms","prompt":"What person and number does λέγει express?","choices":[{"text":"third person plural","correct":false},{"text":"third person singular","correct":true},{"text":"first person singular","correct":false},{"text":"second person singular","correct":false}],"explanation":"Correct: third person singular.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-29","type":"multiple_choice","topic":"verb-forms","prompt":"In λέγει, how many people or things perform the action?","choices":[{"text":"two","correct":false},{"text":"more than one","correct":false},{"text":"one","correct":true}],"explanation":"λέγει is third person singular.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-30","type":"multiple_choice","topic":"verb-forms","prompt":"Which stem remains when -ει is removed from λέγει?","choices":[{"text":"καλε-","correct":false},{"text":"ὑλακτε-","correct":false},{"text":"οἰκε-","correct":false},{"text":"λεγ-","correct":true}],"explanation":"The stem is λεγ-; -ει is the present active third-person singular ending.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-31","type":"multiple_choice","topic":"verb-forms","prompt":"What does μένει mean?","choices":[{"text":"he/she/it barks","correct":false},{"text":"he/she/it lives","correct":false},{"text":"he/she/it stays","correct":true},{"text":"he/she/it calls","correct":false}],"explanation":"Correct: he/she/it stays.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-32","type":"multiple_choice","topic":"verb-forms","prompt":"Which form means “he/she/it stays”?","choices":[{"text":"βλέπει","correct":false},{"text":"μένει","correct":true},{"text":"ἄγει","correct":false},{"text":"βαδίζει","correct":false}],"explanation":"Correct: μένει.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-33","type":"multiple_choice","topic":"verb-forms","prompt":"What person and number does μένει express?","choices":[{"text":"third person singular","correct":true},{"text":"first person singular","correct":false},{"text":"second person singular","correct":false},{"text":"third person plural","correct":false}],"explanation":"Correct: third person singular.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-34","type":"multiple_choice","topic":"verb-forms","prompt":"In μένει, how many people or things perform the action?","choices":[{"text":"one","correct":true},{"text":"two","correct":false},{"text":"more than one","correct":false}],"explanation":"μένει is third person singular.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-35","type":"multiple_choice","topic":"verb-forms","prompt":"Which stem remains when -ει is removed from μένει?","choices":[{"text":"ὑλακτε-","correct":false},{"text":"οἰκε-","correct":false},{"text":"μεν-","correct":true},{"text":"καλε-","correct":false}],"explanation":"The stem is μεν-; -ει is the present active third-person singular ending.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-36","type":"multiple_choice","topic":"verb-forms","prompt":"What does ποιεῖ mean?","choices":[{"text":"he/she/it lives","correct":false},{"text":"he/she/it does or makes","correct":true},{"text":"he/she/it calls","correct":false},{"text":"he/she/it barks","correct":false}],"explanation":"Correct: he/she/it does or makes.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-37","type":"multiple_choice","topic":"verb-forms","prompt":"Which form means “he/she/it does or makes”?","choices":[{"text":"ποιεῖ","correct":true},{"text":"ἄγει","correct":false},{"text":"βαδίζει","correct":false},{"text":"βλέπει","correct":false}],"explanation":"Correct: ποιεῖ.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-38","type":"multiple_choice","topic":"verb-forms","prompt":"What person and number does ποιεῖ express?","choices":[{"text":"first person singular","correct":false},{"text":"second person singular","correct":false},{"text":"third person plural","correct":false},{"text":"third person singular","correct":true}],"explanation":"Correct: third person singular.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-39","type":"multiple_choice","topic":"verb-forms","prompt":"In ποιεῖ, how many people or things perform the action?","choices":[{"text":"more than one","correct":false},{"text":"one","correct":true},{"text":"two","correct":false}],"explanation":"ποιεῖ is third person singular.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-40","type":"multiple_choice","topic":"verb-forms","prompt":"Which meaning belongs to the whole form ποιεῖ?","choices":[{"text":"they do or make","correct":false},{"text":"he/she/it does or makes","correct":true},{"text":"I do or make","correct":false},{"text":"you do or make","correct":false}],"explanation":"Learn contracted forms such as ποιεῖ as whole forms for now.","sourceStatus":"Course-authored exercise"},{"id":"lesson-1-v2-verb-forms-41","type":"multiple_choice","topic":"verb-forms","prompt":"What does φέρει mean?","choices":[{"text":"he/she/it carries","correct":true},{"text":"he/she/it calls","correct":false},{"text":"he/she/it barks","correct":false},{